/* ===== リセット & ルート変数 ===== */
:root {
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --bg-main: #f8fafc;
  --bg-card: #ffffff;
  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;
  --border-color: #e2e8f0;
  --border-focus: #3b82f6;

  /* ブランド＆店舗カラー */
  --primary: #2563eb;
  --primary-hover: #1d4ed8;
  --shibuya-color: #2563eb;
  --shinjuku-color: #059669;
  --ikebukuro-color: #ea580c;

  /* シャドウ */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.03);

  /* 角丸 */
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background-color: var(--bg-main);
  color: var(--text-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  min-height: 100vh;
}

/* ===== アプリコンテナ ===== */
.app-container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px 48px;
  display: flex;
  flex-direction: column;
  gap: 24px;
}

@media (min-width: 768px) {
  .app-container {
    padding: 36px 28px 64px;
    gap: 32px;
  }
}

/* ===== ヘッダー ===== */
.header {
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
}

.title {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

@media (min-width: 768px) {
  .title {
    font-size: 2rem;
  }
}

.subtitle {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
}

@media (min-width: 768px) {
  .subtitle {
    font-size: 1rem;
  }
}

/* ===== メインレイアウト ===== */
.main-layout {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

/* ===== コントロールパネル ===== */
.control-panel {
  display: flex;
  flex-direction: column;
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 16px 20px;
  gap: 16px;
  box-shadow: var(--shadow-sm);
}

@media (min-width: 768px) {
  .control-panel {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    gap: 24px;
    padding: 16px 24px;
  }
}

/* 期間絞り込みボタン群 */
.period-buttons {
  display: inline-flex;
  background-color: #f1f5f9;
  padding: 4px;
  border-radius: var(--radius-md);
  gap: 4px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.period-btn {
  background: transparent;
  border: none;
  font-family: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.period-btn:hover {
  color: var(--primary-hover);
}

.period-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.period-btn-active {
  background-color: var(--bg-card);
  color: var(--primary);
  box-shadow: var(--shadow-sm);
}

.period-btn-active:hover {
  color: var(--primary-hover);
}

/* 店舗トグルボタン群 */
.store-toggles {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  align-items: center;
}

.store-toggle-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: #ffffff;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-full);
  padding: 6px 14px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.store-toggle-btn:hover {
  background-color: #f8fafc;
  border-color: #cbd5e1;
  color: var(--text-primary);
}

.store-toggle-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.store-toggle-indicator {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

/* ===== グラフカード & ラッパー ===== */
.chart-wrapper {
  display: flex;
  flex-direction: column;
}

.chart-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px 16px 24px;
  box-shadow: var(--shadow-md);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

@media (min-width: 768px) {
  .chart-card {
    padding: 24px 28px 32px;
    gap: 20px;
  }
}

.chart-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-primary);
}

.chart-container {
  width: 100%;
  height: 380px;
  min-height: 320px;
}

@media (min-width: 768px) {
  .chart-container {
    height: 440px;
  }
}

/* Rechartsの標準コンテナが幅一杯に広がるよう調整 */
.chart-container .recharts-responsive-container {
  width: 100% !important;
  height: 100% !important;
}

/* ===== 空状態表示 ===== */
.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 48px 24px;
  text-align: center;
  color: var(--text-muted);
  font-size: 0.875rem;
  gap: 8px;
  width: 100%;
  min-height: 240px;
  background-color: #f8fafc;
  border: 1px dashed var(--border-color);
  border-radius: var(--radius-md);
}

/* ===== カスタムツールチップ ===== */
.custom-tooltip {
  background-color: rgba(255, 255, 255, 0.95);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 150px;
}

.tooltip-title {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--text-primary);
  border-bottom: 1px solid var(--border-color);
  padding-bottom: 4px;
  margin-bottom: 2px;
}

.tooltip-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  font-size: 0.8125rem;
}

.tooltip-value {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: var(--text-primary);
}

/* ===== サマリー指標グリッド & カード ===== */
.stats-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 640px) {
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .stats-grid {
    grid-template-columns: repeat(3, 1fr);
    gap: 20px;
  }
}

.stats-card {
  background-color: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  display: flex;
  flex-direction: column;
  gap: 14px;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.stats-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow-md);
}

.stats-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--border-color);
}

.stats-color-badge {
  width: 12px;
  height: 12px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.stats-store-name {
  font-size: 1.05rem;
  font-weight: 700;
  color: var(--text-primary);
}

.stats-metric-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
}

.stats-metric-label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
}

.stats-metric-value {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}

export type StoreKey = 'shibuya' | 'shinjuku' | 'ikebukuro';

export interface MonthlyVisitorRecord {
  month: string;
  shibuya: number;
  shinjuku: number;
  ikebukuro: number;
}

export interface StoreConfig {
  id: string;
  name: string;
  color: string;
  key: StoreKey;
  visible: boolean;
}

export type PeriodFilter = 'all' | 'first-half' | 'second-half';

export interface StoreStats {
  name: string;
  total: number;
  average: number;
  peakMonth: string;
  peakValue: number;
  color: string;
  visible: boolean;
}

import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from 'recharts';
import { MonthlyVisitorRecord, StoreConfig } from '../types';

interface VisitorChartProps {
  data?: MonthlyVisitorRecord[];
  stores?: StoreConfig[];
}

interface TooltipPayloadItem {
  name: string;
  value: number;
  color: string;
  dataKey: string;
}

interface CustomTooltipProps {
  active?: boolean;
  payload?: TooltipPayloadItem[];
  label?: string;
}

const CustomTooltip = ({ active, payload, label }: CustomTooltipProps) => {
  if (active && payload && payload.length > 0) {
    return (
      <div className="custom-tooltip">
        <div className="tooltip-title">{label || ''}</div>
        {payload.map((entry) => {
          const valText =
            typeof entry?.value === 'number'
              ? `${entry.value.toLocaleString()}人`
              : '-';
          return (
            <div key={entry?.dataKey ?? entry?.name} className="tooltip-item">
              <span style={{ color: entry?.color || '#000000', fontWeight: 600 }}>
                {entry?.name || '店舗'}
              </span>
              <span className="tooltip-value">{valText}</span>
            </div>
          );
        })}
      </div>
    );
  }
  return null;
};

const VisitorChart = ({ data = [], stores = [] }: VisitorChartProps) => {
  const visibleStores = stores.filter((store) => store.visible);

  return (
    <div className="chart-wrapper">
      <div className="chart-card">
        <h2 className="chart-title">月別来客数推移</h2>
        <div className="chart-container">
          {visibleStores.length === 0 ? (
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                height: '100%',
                color: 'var(--text-secondary)',
                fontSize: '0.9375rem',
              }}
            >
              表示する店舗を選択してください
            </div>
          ) : (
            <ResponsiveContainer width="100%" height="100%">
              <LineChart
                data={data}
                margin={{ top: 16, right: 24, left: 16, bottom: 8 }}
                accessibilityLayer
              >
                <CartesianGrid
                  strokeDasharray="3 3"
                  stroke="#e2e8f0"
                  vertical={false}
                />
                <XAxis
                  dataKey="month"
                  stroke="#64748b"
                  fontSize={12}
                  tickLine={false}
                  axisLine={{ stroke: '#cbd5e1' }}
                  aria-label="月"
                />
                <YAxis
                  stroke="#64748b"
                  fontSize={12}
                  tickLine={false}
                  axisLine={{ stroke: '#cbd5e1' }}
                  tickFormatter={(val: number) =>
                    typeof val === 'number' ? `${val.toLocaleString()}人` : ''
                  }
                  width={70}
                  aria-label="来客数（人）"
                />
                <Tooltip content={<CustomTooltip />} />
                <Legend
                  verticalAlign="top"
                  align="right"
                  wrapperStyle={{ paddingBottom: '16px', fontSize: '13px' }}
                />
                {visibleStores.map((store) => (
                  <Line
                    key={store.id}
                    type="monotone"
                    dataKey={store.key}
                    name={store.name}
                    stroke={store.color}
                    strokeWidth={2.5}
                    dot={{
                      r: 4,
                      fill: store.color,
                      strokeWidth: 2,
                      stroke: '#ffffff',
                    }}
                    activeDot={{
                      r: 7,
                      fill: store.color,
                      stroke: '#ffffff',
                      strokeWidth: 2,
                    }}
                  />
                ))}
              </LineChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>
    </div>
  );
};

export default VisitorChart;

import type { CSSProperties } from 'react';
import { StoreConfig, PeriodFilter, StoreKey } from '../types';

interface ChartControlsProps {
  currentPeriod: PeriodFilter;
  onPeriodChange: (period: PeriodFilter) => void;
  stores?: StoreConfig[];
  onToggleStore: (key: StoreKey) => void;
}

const ChartControls = ({
  currentPeriod,
  onPeriodChange,
  stores = [],
  onToggleStore,
}: ChartControlsProps) => {
  const visibleCount = stores.filter((s) => s.visible).length;

  return (
    <div className="control-panel">
      {/* 期間絞り込みボタン群 */}
      <div className="period-buttons" role="group" aria-label="表示期間選択">
        <button
          type="button"
          className={
            currentPeriod === 'all'
              ? 'period-btn period-btn-active'
              : 'period-btn'
          }
          onClick={() => onPeriodChange('all')}
          aria-pressed={currentPeriod === 'all'}
        >
          通年 (1月〜12月)
        </button>
        <button
          type="button"
          className={
            currentPeriod === 'first-half'
              ? 'period-btn period-btn-active'
              : 'period-btn'
          }
          onClick={() => onPeriodChange('first-half')}
          aria-pressed={currentPeriod === 'first-half'}
        >
          上半期 (1月〜6月)
        </button>
        <button
          type="button"
          className={
            currentPeriod === 'second-half'
              ? 'period-btn period-btn-active'
              : 'period-btn'
          }
          onClick={() => onPeriodChange('second-half')}
          aria-pressed={currentPeriod === 'second-half'}
        >
          下半期 (7月〜12月)
        </button>
      </div>

      {/* 店舗表示トグルボタン群 */}
      <div className="store-toggles" role="group" aria-label="店舗表示切替">
        {stores.map((store) => {
          const isVisible = store.visible;
          const isOnlyOneVisible = isVisible && visibleCount === 1;

          const buttonStyle: CSSProperties = {
            borderColor: isVisible ? store.color : 'var(--border-color)',
            backgroundColor: isVisible ? '#ffffff' : '#f8fafc',
            opacity: isVisible ? 1 : 0.6,
            cursor: isOnlyOneVisible ? 'not-allowed' : 'pointer',
          };

          const indicatorStyle: CSSProperties = {
            backgroundColor: store.color,
            opacity: isVisible ? 1 : 0.3,
            transform: isVisible ? 'scale(1)' : 'scale(0.8)',
          };

          return (
            <button
              key={store.id}
              type="button"
              className="store-toggle-btn"
              onClick={() => {
                if (isOnlyOneVisible) {
                  return;
                }
                onToggleStore(store.key);
              }}
              aria-pressed={isVisible}
              title={
                isOnlyOneVisible
                  ? '最低1つの店舗を表示する必要があります'
                  : undefined
              }
              style={buttonStyle}
            >
              <span className="store-toggle-indicator" style={indicatorStyle} />
              <span>{store.name}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default ChartControls;

import { StoreStats } from '../types';

interface StoreSummaryProps {
  stats?: StoreStats[];
}

const StoreSummary = ({ stats = [] }: StoreSummaryProps) => {
  if (stats.length === 0) {
    return (
      <div
        className="stats-card"
        style={{
          textAlign: 'center',
          color: 'var(--text-secondary)',
          padding: '32px 16px',
        }}
      >
        集計データがありません
      </div>
    );
  }

  return (
    <div className="stats-grid">
      {stats.map((item) => {
        const isHidden = item.visible === false;

        return (
          <div
            key={item.name}
            className="stats-card"
            style={
              isHidden
                ? {
                    opacity: 0.5,
                    filter: 'grayscale(0.7)',
                    backgroundColor: '#f8fafc',
                  }
                : undefined
            }
          >
            <div className="stats-header">
              <span
                className="stats-color-badge"
                style={{ backgroundColor: item.color }}
              />
              <h3 className="stats-store-name">{item.name}</h3>
              {isHidden && (
                <span
                  style={{
                    fontSize: '0.75rem',
                    color: 'var(--text-muted)',
                    marginLeft: 'auto',
                  }}
                >
                  非表示中
                </span>
              )}
            </div>

            <div className="stats-metric-row">
              <span className="stats-metric-label">期間合計来客数</span>
              <span className="stats-metric-value">
                {item.total.toLocaleString()} 人
              </span>
            </div>

            <div className="stats-metric-row">
              <span className="stats-metric-label">月平均来客数</span>
              <span className="stats-metric-value">
                {item.average.toLocaleString()} 人
              </span>
            </div>

            <div className="stats-metric-row">
              <span className="stats-metric-label">ピーク月</span>
              <span className="stats-metric-value">
                {item.peakMonth} ({item.peakValue.toLocaleString()}人)
              </span>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default StoreSummary;

import { useState, useMemo } from 'react';
import {
  MonthlyVisitorRecord,
  StoreConfig,
  PeriodFilter,
  StoreKey,
  StoreStats,
} from './types';
import VisitorChart from './components/VisitorChart';
import ChartControls from './components/ChartControls';
import StoreSummary from './components/StoreSummary';

// 期間絞り込み用のインデックス定数（マジックナンバー排除）
const FIRST_HALF_START_INDEX = 0;
const FIRST_HALF_END_INDEX = 6;
const SECOND_HALF_START_INDEX = 6;
const SECOND_HALF_END_INDEX = 12;

// 1月〜12月の初期来客数データ
const initialMonthlyData: MonthlyVisitorRecord[] = [
  { month: '1月', shibuya: 8400, shinjuku: 11200, ikebukuro: 7200 },
  { month: '2月', shibuya: 7900, shinjuku: 10500, ikebukuro: 6800 },
  { month: '3月', shibuya: 10200, shinjuku: 13400, ikebukuro: 8900 },
  { month: '4月', shibuya: 9800, shinjuku: 12100, ikebukuro: 8400 },
  { month: '5月', shibuya: 11500, shinjuku: 13800, ikebukuro: 10100 },
  { month: '6月', shibuya: 9200, shinjuku: 11900, ikebukuro: 7900 },
  { month: '7月', shibuya: 12100, shinjuku: 14200, ikebukuro: 10800 },
  { month: '8月', shibuya: 13800, shinjuku: 15600, ikebukuro: 12400 },
  { month: '9月', shibuya: 10400, shinjuku: 12800, ikebukuro: 9200 },
  { month: '10月', shibuya: 11100, shinjuku: 13500, ikebukuro: 9800 },
  { month: '11月', shibuya: 10600, shinjuku: 13100, ikebukuro: 9300 },
  { month: '12月', shibuya: 14200, shinjuku: 16800, ikebukuro: 12900 },
];

// 初期店舗設定
const initialStores: StoreConfig[] = [
  {
    id: 'store-shibuya',
    name: '渋谷店',
    color: '#2563eb',
    key: 'shibuya',
    visible: true,
  },
  {
    id: 'store-shinjuku',
    name: '新宿店',
    color: '#059669',
    key: 'shinjuku',
    visible: true,
  },
  {
    id: 'store-ikebukuro',
    name: '池袋店',
    color: '#ea580c',
    key: 'ikebukuro',
    visible: true,
  },
];

const App = () => {
  const [stores, setStores] = useState<StoreConfig[]>(initialStores);
  const [period, setPeriod] = useState<PeriodFilter>('all');

  // 表示中の店舗数
  const visibleStoresCount = useMemo(
    () => stores.filter((store) => store.visible).length,
    [stores]
  );

  // 店舗の表示/非表示切り替え（最低1店舗は表示を維持）
  const handleToggleStore = (key: StoreKey) => {
    setStores((prevStores) => {
      const target = prevStores.find((store) => store.key === key);
      if (!target) return prevStores;

      const currentVisibleCount = prevStores.filter((s) => s.visible).length;
      if (target.visible && currentVisibleCount <= 1) {
        return prevStores;
      }

      return prevStores.map((store) =>
        store.key === key ? { ...store, visible: !store.visible } : store
      );
    });
  };

  // 全店舗を表示状態に戻す復帰ハンドラ
  const handleShowAllStores = () => {
    setStores((prevStores) =>
      prevStores.map((store) => ({ ...store, visible: true }))
    );
  };

  // 期間フィルターに応じたグラフデータ
  const filteredData = useMemo(() => {
    if (period === 'first-half') {
      return initialMonthlyData.slice(
        FIRST_HALF_START_INDEX,
        FIRST_HALF_END_INDEX
      );
    }
    if (period === 'second-half') {
      return initialMonthlyData.slice(
        SECOND_HALF_START_INDEX,
        SECOND_HALF_END_INDEX
      );
    }
    return initialMonthlyData;
  }, [period]);

  // 各店舗のサマリー指標計算（非表示フラグも含めて整合性を保つ）
  const statsList: StoreStats[] = useMemo(() => {
    return stores.map((store) => {
      const records = filteredData;
      const values = records.map((record) => record[store.key]);

      const total = values.reduce((sum, val) => sum + val, 0);
      const average = values.length > 0 ? Math.round(total / values.length) : 0;

      let peakValue = 0;
      let peakMonth = '-';

      records.forEach((record) => {
        const val = record[store.key];
        if (val > peakValue) {
          peakValue = val;
          peakMonth = record.month;
        }
      });

      return {
        name: store.name,
        total,
        average,
        peakMonth,
        peakValue,
        color: store.color,
        visible: store.visible,
      };
    });
  }, [stores, filteredData]);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">店舗別来客数ダッシュボード</h1>
        <p className="subtitle">
          渋谷店・新宿店・池袋店の月別推移比較とパフォーマンス指標
        </p>
      </header>

      <main className="main-layout">
        <ChartControls
          currentPeriod={period}
          onPeriodChange={setPeriod}
          stores={stores}
          onToggleStore={handleToggleStore}
        />

        {visibleStoresCount === 0 ? (
          <div className="empty-state">
            <p style={{ color: 'var(--text-secondary)', fontWeight: 600 }}>
              表示中の店舗がありません
            </p>
            <p>グラフとサマリーを確認するには店舗を選択してください。</p>
            <button
              type="button"
              className="period-btn period-btn-active"
              onClick={handleShowAllStores}
              style={{ marginTop: '8px' }}
            >
              すべての店舗を表示する
            </button>
          </div>
        ) : (
          <>
            <VisitorChart data={filteredData} stores={stores} />
            <StoreSummary stats={statsList} />
          </>
        )}
      </main>
    </div>
  );
};

export default App;
